const k = $('Start per Kette').first().json.body;
const ab = Number(k.zweitmeinung_ab_score || 3);
const max = Number(k.zweitmeinung_max_stellen || 100);
// Nur lokal bewertete Stellen mit gutem Score – Claude-Bewertungen werden nicht doppelt bezahlt.
return $input
  .all()
  .map((i) => i.json)
  .filter((r) => r.id && Number(r.passung_score) >= ab && /^(ollama|claude):/.test(String(r.modell_bewertung || '')) && !String(r.modell_bewertung).includes(k.zweitmeinung_modell || 'claude-sonnet-5-5') && !r.duplikat_von)
  .sort((a, b) => b.passung_score - a.passung_score)
  .slice(0, max)
  .map((r) => ({ json: { ...r, _direkt: false } }));

const row = $('Schleife: eine Stelle nach der anderen').first().json;
const cache = $('Seitentext aus Cache').first().json;
const k = $('Start per Kette').first().json.body;

const vorlage = String($json.text || '').split('\n').filter((z) => !/^#(?!#)/.test(z)) /* '# …' = Kommentar, '## …' = Überschrift bleibt */.join('\n');
const [system, anfrage] = vorlage.split('=== ANFRAGE ===').map((t) => t.trim());
const fuellen = (t, werte) => t.replace(/\{\{(\w+)\}\}/g, (m, key) => (key in werte ? werte[key] : m));

const fakten = [
  `Jobtitel: ${row.jobtitel || '-'}`,
  `Firma: ${row.firma || '-'}`,
  `Ort: ${row.ort || '-'}`,
  `Remote: ${row.remote || '-'}`,
  `Remote-Regel (wörtlich): ${row.remote_regel_wortlaut || '-'}`,
  `Gehalt: ${row.gehalt || '-'}`,
  `Vertragsform: ${row.vertragsform || '-'}`,
  `Bewerbungsweg: ${row.bewerbungsweg || '-'}`,
  `Veröffentlicht: ${row.veroeffentlichungsdatum || 'unbekannt'}`,
  `Zusammenfassung: ${row.kurze_zusammenfassung || '-'}`,
].join('\n');

// ---- Signalwort-Check per Code (findet zuverlässig, erfindet nichts) ----
const seitentext = cache && cache.ok ? String(cache.text) : '';
const suchtext = (seitentext + '\n' + (row.remote_regel_wortlaut || '')).toLowerCase();
const finde = (liste) =>
  String(liste || '')
    .split(',')
    .map((w) => w.trim().toLowerCase())
    .filter((w) => w && suchtext.includes(w));
const plus = finde(k.signal_plus);
const minus = finde(k.signal_minus);
const signale =
  `Automatisch im Anzeigentext gefundene Signalwörter zum Arbeitsort:\n` +
  `- Plus: ${plus.length ? plus.join(', ') : 'keine'}\n` +
  `- Minus: ${minus.length ? minus.join(', ') : 'keine'}\n` +
  `(Prüfe im Text, in welchem Zusammenhang sie stehen – z. B. kann "hybrid" auch "nicht hybrid" heißen.)`;

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['passung_score', 'pflichtkriterien_erfuellt', 'begruendung', 'luecken', 'offene_fragen', 'warnsignale', 'dev_skills_nutzen', 'dev_skills_wie'],
  properties: {
    dev_skills_nutzen: { type: 'string', enum: ['hoch', 'mittel', 'gering', 'keiner'] },
    dev_skills_wie: { type: 'string', description: 'Welche Entwickler-Skills konkret wofür helfen' },
    passung_score: { type: 'integer', description: '1 (passt nicht) bis 5 (passt sehr gut)' },
    pflichtkriterien_erfuellt: { type: 'string', enum: ['ja', 'nein', 'unklar'] },
    begruendung: { type: 'string' },
    luecken: { type: 'string' },
    offene_fragen: { type: 'string' },
    warnsignale: { type: 'string' },
  },
};

return [
  {
    json: {
      system,
      anfrage: fuellen(anfrage, { HEUTE: $now.toFormat('yyyy-MM-dd'), KRITERIEN: k.kriterien, FAKTEN: fakten + '\n\n' + signale, URL: row.url, SEITENTEXT: '{{SEITENTEXT}}' }),
      seitentext: seitentext || '(kein Seitentext im Cache – nur Fakten verwenden)',
      schema: SCHEMA,
      anbieter_override: k.anbieter_override || '',
      funktion: k.funktion_override || 'bewertung', // Modell laut Einstellungen
      claude_modell_override: k.claude_modell_override || '',
      claude_effort_override: k.claude_effort_override || '',
      ollama_denken_override: k.ollama_denken_override || '',
      kontext: {
        id: row.id,
        signale_plus: plus.join(', '),
        signale_minus: minus.join(', '),
        vorher_score: row.passung_score || null,
        vorher_modell: row.modell_bewertung || '',
      },
    },
  },
];

const r = $json;
const jetzt = new Date().toISOString();
if (r._direkt) {
  return [{ json: { id: r.id, passung_score: 1, bewertung: 'passt nicht', bewertung_begruendung: r._grund, pflichtkriterien_erfuellt: '', luecken: '', offene_fragen: '', warnsignale: '', modell_bewertung: 'regel', bewertet_am: jetzt } }];
}
const modell = `${r.anbieter || '?'}:${r.modell || '?'}`;
if (!r.ok && r.kontext && r.kontext.vorher_score) {
  // Zweitmeinung fehlgeschlagen (z. B. Netzwerk, Guthaben leer): alte Bewertung behalten.
  return [{ json: { id: r.kontext.id, modell_bewertung: r.kontext.vorher_modell } }];
}
if (!r.ok) {
  return [{ json: { id: r.kontext && r.kontext.id, bewertung: 'fehler', bewertung_begruendung: 'KI-Fehler: ' + (r.fehler || 'keine Antwort'), modell_bewertung: modell, bewertet_am: jetzt } }];
}
const d = r.daten;
let score = Math.round(Number(d.passung_score));
if (!Number.isFinite(score)) score = 3;
score = Math.min(5, Math.max(1, score));
const bewertung = score >= 4 ? 'passt gut' : score === 3 ? 'passt teilweise' : 'passt nicht';
return [
  {
    json: {
      id: r.kontext.id,
      passung_score: score,
      bewertung,
      // Zusatzinfos als [Markierungen] am Ende – die Ergebnis-Seite zeigt sie als eigene Felder an.
      bewertung_begruendung:
        String(d.begruendung || '') +
        ` [Dev-Skills: ${d.dev_skills_nutzen || '?'}${d.dev_skills_wie ? ' – ' + d.dev_skills_wie : ''}]` +
        ` [Signalwörter + ${r.kontext.signale_plus || '–'} | − ${r.kontext.signale_minus || '–'}]` +
        // Bei einer Zweitmeinung: vorherige lokale Bewertung festhalten (zum Vergleichen)
        (r.anbieter === 'claude' && /^(ollama|claude):/.test(String(r.kontext.vorher_modell || '')) && String(r.kontext.vorher_modell) !== `claude:${r.modell}` && r.kontext.vorher_score
          ? ` [Vorher ${String(r.kontext.vorher_modell).startsWith('ollama') ? 'lokal' : 'Haiku'}: ${r.kontext.vorher_score}]`
          : ''),
      pflichtkriterien_erfuellt: String(d.pflichtkriterien_erfuellt || ''),
      luecken: String(d.luecken || ''),
      offene_fragen: String(d.offene_fragen || ''),
      warnsignale: String(d.warnsignale || ''),
      modell_bewertung: modell,
      bewertet_am: jetzt,
    },
  },
];

const z = {};
for (const i of $input.all()) z[i.json.bewertung || 'ohne'] = (z[i.json.bewertung || 'ohne'] || 0) + 1;
return [{ json: { bewertet: $input.all().length, ergebnis: z, tipp: 'Ergebnis-Seite: http://localhost:3000/ergebnisse' } }];
